def leave_column(self, column):
    count = self.columns[column]
    if count == 1:
        del self.columns[column]
        # If this column belonged to an orphan-rooted chain, hold it
        # off-limits for ``orphan_cooldown`` more iteration steps so
        # an unrelated chain doesn't immediately land on the same x.
        if column in self._orphan_columns:
            self._orphan_columns.discard(column)
            if self.orphan_cooldown > 0:
                self._column_cooldown[column] = self.orphan_cooldown
    else:
        self.columns[column] = count - 1

def recompute_grid(self):
    self.reset_columns()
    self.reset_rows()
    self._orphan_columns = set()
    self._column_cooldown = {}

    for node in sort_by_generation(list(self.commits)):
        # Tick down per-column cooldowns at the start of every step so
        # ``orphan_cooldown`` translates into N processed nodes of
        # mandatory separation.
        if self._column_cooldown:
            for col in list(self._column_cooldown):
                remaining = self._column_cooldown[col] - 1
                if remaining <= 0:
                    del self._column_cooldown[col]
                else:
                    self._column_cooldown[col] = remaining

        if node.column is None:
            # Node is either root or its parent is not in items. This
            # happens when tree loading is in progress. Allocate new
            # columns for such nodes.
            node.column = self.alloc_column()
            if not node.parents:
                # Mark this column as the start of an orphan chain so
                # leave_column() can apply cooldown when it ends.
                self._orphan_columns.add(node.column)

        node.row = self.alloc_cell(node.column, node.tags)

